gAS(){return"Nexus"},
gAZ(a){return"\u0420\u043e\u0437\u043c\u0456\u0440"},
gAr(){return"\u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043e"},
gB_(){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e \u0437"},
gAU(){return"\u0412\u0456\u043d \u043d\u0430\u0434\u0456\u0439\u0434\u0435 \u044f\u043a \u043d\u043e\u0432\u0438\u0439 Nexus. \u041d\u0456\u0447\u043e\u0433\u043e \u0437 \u0442\u043e\u0433\u043e, \u0449\u043e \u0443 \u0432\u0430\u0441 \u0443\u0436\u0435 \u0454, \u043d\u0435 \u0431\u0443\u0434\u0435 \u0437\u043c\u0456\u043d\u0435\u043d\u043e."},
